head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_schdl_adm_itm_tp_cd = "";
scwin.v_ldMktTpCd = "";

// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.v_schdl_adm_itm_tp_cd = $c.frame.path("../").scwin.v_schdl_adm_itm_tp_cd;
        scwin.v_ldMktTpCd = $c.frame.path("../").scwin.v_ldMktTpCd;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39205.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39205.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&LD_MKT_TP_CD=1";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=";
    url += "&SCHDL_ADM_ITM_TP_CD=" + scwin.v_schdl_adm_itm_tp_cd;
    url += "&SCREN_ID=" + 'ULDSTF39204.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_MxDataSet_schdl_tp_cd_1",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "MxDataSet_schdl_tp_cd_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&LD_MKT_TP_CD=2";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=";
    url += "&SCHDL_ADM_ITM_TP_CD=" + scwin.v_schdl_adm_itm_tp_cd;
    url += "&SCREN_ID=" + 'ULDSTF39204.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_MxDataSet_schdl_tp_cd_2",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "MxDataSet_schdl_tp_cd_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&LD_MKT_TP_CD=6";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=";
    url += "&SCHDL_ADM_ITM_TP_CD=" + scwin.v_schdl_adm_itm_tp_cd;
    url += "&SCREN_ID=" + 'ULDSTF39204.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions3 = {
        id : "sbm_MxDataSet_schdl_tp_cd_3",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "MxDataSet_schdl_tp_cd_3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
